insert into cisco.cisco_decks (id, slug, title, sermon_id, metadata)
insert into cisco.cisco_slides (deck_id, position, html, outline_html, bg, notes)
values
  ('c1000000-0000-4000-8000-000000000007', 1, '<img class="slide-image" src="/sermons/ask-better-questions/slides/01.jpg" alt="Hold On to What Is Good — Open to every good gift. Anchored in Christ.">', '<p><strong>Slide &mdash; We are in a series, Hold On To What Is Good.</strong></p>', null, 'Series title.'),
  ('c1000000-0000-4000-8000-000000000007', 2, '<img class="slide-image" src="/sermons/ask-better-questions/slides/02.jpg" alt="1 Thessalonians 5:21–22 (ESV) — but test everything; hold fast what is good. Abstain from every form of evil.">', '<p><strong>Slide &mdash; 1 Thessalonians 5:21</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000007', 3, '<img class="slide-image" src="/sermons/ask-better-questions/slides/03.jpg" alt="Lesson 2 — Ask Better Questions">', '<p><strong>Slide &mdash; Today&rsquo;s lesson, Ask Better Questions.</strong></p><p>Kids go through a phase and ask why, how, what&hellip;</p><p>Marriage &mdash; you asked the right questions and she married you.</p><p>Aren&rsquo;t you glad that someone before you asked better questions? Holidays, more dessert choices. Transportation &mdash; is there something better than a wagon, from cars to cars with A/C.</p><p><strong>History &mdash; we enjoy wonderful things because others dared to ask better questions:</strong></p><p><strong>1. Alexander Fleming</strong> &mdash; penicillin (1928). Noticed that mold had killed bacteria in one of his cultures. Instead of simply discarding the sample, <strong>he investigated</strong> what had happened.</p><p><strong>2. Isaac Newton</strong> &mdash; gravity. Sat in the garden of his family home and saw an apple fall straight down, rather than sideways or up. Wondered why it always fell toward the Earth&rsquo;s center &mdash; the start of his law of universal gravitation.</p><p><strong>3. Albert Einstein</strong> &mdash; relativity (1905). Explored questions about light, motion, space, and time. Imagined <strong>what it would be like</strong> to travel alongside a beam of light. His willingness to <strong>question established assumptions</strong> helped transform physics.</p><p>Is there something to be learned by asking a better question?</p>', null, 'Hold on the title through the opening stories and the three examples.'),
  ('c1000000-0000-4000-8000-000000000007', 4, '<img class="slide-image" src="/sermons/ask-better-questions/slides/04.jpg" alt="Proverbs 18:15 (ESV) — An intelligent heart acquires knowledge, and the ear of the wise seeks knowledge.">', '<p><strong>Slide &mdash; Proverbs 18:15 says it beautifully:</strong></p><p><em>&ldquo;The heart of the discerning acquires knowledge, for the ears of the wise seek it out.&rdquo;</em> (NIV)</p>', null, 'Notes are the NIV; the slide is the ESV.'),
  ('c1000000-0000-4000-8000-000000000007', 5, '<img class="slide-image" src="/sermons/ask-better-questions/slides/05.jpg" alt="The posture of wisdom is, “Let me understand this better.”">', '<p>The posture of wisdom is not, <em>&ldquo;Let me find what is wrong with this.&rdquo;</em></p><p><strong>It is, &ldquo;Let me understand this better.&rdquo;</strong></p><p>Wisdom is <strong>curious</strong> before it is critical.</p><p>Wisdom <strong>begins</strong> by asking, &ldquo;What can I learn?&rdquo;</p><p><strong>There&rsquo;s a difference between being critical vs seeking.</strong></p><p>Matthew 6:33 &mdash; Seek first the Kingdom of God. In Spanish, &ldquo;buscar.&rdquo;</p><p>Illustration: my dad told me to go get the garden hoe from the tool shed &mdash; not motivated, not likely to find it.</p><p>Illustration: Christmas presents under the tree, Ofilia &mdash; so motivated she kept looking until she found out what was inside.</p><p><strong>Whoever really wants to find something seeks it out, and finds it. Seek first the kingdom &mdash; God will make sure you find it.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000007', 6, '<img class="slide-image" src="/sermons/ask-better-questions/slides/06.jpg" alt="Acts 17:11 (ESV) — Now these Jews were more noble than those in Thessalonica; they received the word with all eagerness, examining the Scriptures daily to see if these things were so.">', '<p><strong>Acts 17:11 &mdash; The Bereans</strong></p><p>They &ldquo;received the message with great eagerness and examined the Scriptures every day to see if what Paul said was true.&rdquo;</p><p>They were <strong>open enough to listen</strong> and <strong>grounded enough to examine</strong>.</p><p>&ldquo;Questioning the preacher was called noble.&rdquo;</p><p>Nobody in that church got lectured for asking.</p>', null, 'These Jews stood out because other Jews were not like this.'),
  ('c1000000-0000-4000-8000-000000000007', 7, '<img class="slide-image" src="/sermons/ask-better-questions/slides/07.jpg" alt="A faith that welcomes questions isn’t weaker.">', '<p><strong>A faith that welcomes questions isn&rsquo;t weaker.</strong> (It&rsquo;s Berean.) Being informed!</p><p>These Jews stood out because other Jews were not like this.</p><p><strong>What team would you pick?</strong></p><p>Is this a practice that you incorporate in your spiritual journey? Ask better questions &middot; ask deeper questions &middot; seek to understand.</p><p>Questions lead to <strong>conversations</strong>, to <strong>investigating</strong>, to <strong>sharing</strong>.</p><p>Someone in the kingdom gets blessed.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000007', 8, '<img class="slide-image" src="/sermons/ask-better-questions/slides/08.jpg" alt="God Came Near — Max Lucado">', '<p><strong>God Came Near</strong> by Max Lucado</p>', null, null),
  ('c1000000-0000-4000-8000-000000000007', 9, '<img class="slide-image" src="/sermons/ask-better-questions/slides/09.jpg" alt="It — Craig Groeschel">', '<p><strong>It</strong> by Craig Groeschel</p>', null, null),
  ('c1000000-0000-4000-8000-000000000007', 10, '<img class="slide-image" src="/sermons/ask-better-questions/slides/10.jpg" alt="Life On Purpose — Jeff Little, Milestone Church">', '<p><strong>Life On Purpose</strong> by Jeff Little</p>', null, null),
  ('c1000000-0000-4000-8000-000000000007', 11, '<img class="slide-image" src="/sermons/ask-better-questions/slides/11.jpg" alt="Life On Purpose, a study in Colossians — seven weeks">', '<p>Life On Purpose &mdash; a study in Colossians, seven weeks: Christ in You &middot; Your Thinking &middot; Your Relationships &middot; Your Peace &middot; Your Family &middot; Your Work &middot; Make the Most of Every Opportunity.</p>', null, null)
insert into cisco.cisco_deck_state (deck_id, current_slide, is_live, is_blank)
